String _humanize(String s) {
  final spaced = s.replaceAll('_', ' ');
  return spaced.isEmpty ? spaced : spaced[0].toUpperCase() + spaced.substring(1);
}

/// Label of a species-file field such as `body_mass_g` in [lang].
String fieldLabelFor(String lang, String field) {
  final texts = kFieldLabels[field];
  return texts?[lang] ?? texts?['en'] ?? _humanize(field);
}

/// A categorical value such as `Forest` or `Full migrant` in [lang]; other values are returned unchanged.
String valueLabelFor(String lang, String value) {
  final texts = kValueLabels[value];
  return texts?[lang] ?? texts?['en'] ?? value;
}
